  1 | import { useEffect, useRef, useState, useCallback } from "react";
  2 | 
  3 | const FFT_SIZE = 256;
  4 | const SMOOTHING = 0.8;
  5 | 
  6 | export function useAudioVisualizer(
  7 |   audioRef: React.RefObject<HTMLAudioElement | null>,
  8 |   isActive: boolean
  9 | ) {
 10 |   const [frequencyData, setFrequencyData] = useState<Uint8Array>(
 11 |     new Uint8Array(FFT_SIZE / 2)
 12 |   );
 13 |   const [waveformData, setWaveformData] = useState<Uint8Array>(
 14 |     new Uint8Array(FFT_SIZE)
 15 |   );
 16 |   const [isVisualizerActive, setIsVisualizerActive] = useState(false);
 17 | 
 18 |   const audioContextRef = useRef<AudioContext | null>(null);
 19 |   const analyserRef = useRef<AnalyserNode | null>(null);
 20 |   const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);
 21 |   const rafRef = useRef<number | null>(null);
 22 |   const freqBufRef = useRef<Uint8Array>(new Uint8Array(FFT_SIZE / 2));
 23 |   const waveBufRef = useRef<Uint8Array>(new Uint8Array(FFT_SIZE));
 24 | 
 25 |   const cleanup = useCallback(() => {
 26 |     if (rafRef.current !== null) {
 27 |       cancelAnimationFrame(rafRef.current);
 28 |       rafRef.current = null;
 29 |     }
 30 |     if (audioContextRef.current && audioContextRef.current.state !== "closed") {
 31 |       audioContextRef.current.close().catch(() => {});
 32 |     }
 33 |     audioContextRef.current = null;
 34 |     analyserRef.current = null;
 35 |     sourceRef.current = null;
 36 |     setIsVisualizerActive(false);
 37 |   }, []);
 38 | 
 39 |   useEffect(() => {
 40 |     const audio = audioRef.current;
 41 |     if (!audio || !isActive) {
 42 |       cleanup();
 43 |       return;
 44 |     }
 45 | 
 46 |     // Avoid re-creating if already connected to the same audio element
 47 |     if (audioContextRef.current && sourceRef.current) {
 48 |       setIsVisualizerActive(true);
 49 |       return;
 50 |     }
 51 | 
 52 |     try {
 53 |       const AudioCtx =
 54 |         window.AudioContext ||
 55 |         (window as unknown as { webkitAudioContext: typeof AudioContext })
 56 |           .webkitAudioContext;
 57 |       if (!AudioCtx) {
 58 |         console.warn("[Llama Player] AudioContext not available");
 59 |         return;
 60 |       }
 61 | 
 62 |       const ctx = new AudioCtx();
 63 |       const analyser = ctx.createAnalyser();
 64 |       analyser.fftSize = FFT_SIZE;
 65 |       analyser.smoothingTimeConstant = SMOOTHING;
 66 | 
 67 |       const source = ctx.createMediaElementSource(audio);
 68 |       source.connect(analyser);
 69 |       analyser.connect(ctx.destination);
 70 | 
 71 |       audioContextRef.current = ctx;
 72 |       analyserRef.current = analyser;
 73 |       sourceRef.current = source;
 74 | 
 75 |       setIsVisualizerActive(true);
 76 | 
 77 |       const freqBuf = freqBufRef.current;
 78 |       const waveBuf = waveBufRef.current;
 79 | 
 80 |       const tick = () => {
 81 |         if (analyserRef.current) {
 82 |           analyserRef.current.getByteFrequencyData(freqBuf);
 83 |           analyserRef.current.getByteTimeDomainData(waveBuf);
 84 |           setFrequencyData(new Uint8Array(freqBuf));
 85 |           setWaveformData(new Uint8Array(waveBuf));
 86 |         }
 87 |         rafRef.current = requestAnimationFrame(tick);
 88 |       };
 89 | 
 90 |       rafRef.current = requestAnimationFrame(tick);
 91 |     } catch (err) {
 92 |       console.warn("[Llama Player] AudioContext error:", err);
 93 |       cleanup();
 94 |     }
 95 | 
 96 |     return () => {
 97 |       cleanup();
 98 |     };
 99 |   }, [audioRef, isActive, cleanup]);
100 | 
101 |   return {
102 |     frequencyData,
103 |     waveformData,
104 |     isActive: isVisualizerActive,
105 |   };
106 | }
